1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9		"unicode/utf8"
10	)
11	
12	// Heartbeat is one telemetry record reported by a node.
13	//
14	// JSON input uses snake_case field names:
15	//
16	//	node          string   node id (required, non-empty)
17	//	seq           integer  sequence number (required, > 0)
18	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00
19	//	                      (required; year 0000-9999, numeric offset hour 00-23
20	//	                      and minute 00-59 on the minute — +24:00 and a folded
21	//	                      offset such as +00:60 are rejected, not normalised;
22	//	                      a fractional second, written with either "." or ","
23	//	                      as its decimal separator, must be exactly
24	//	                      representable at nanosecond precision — more than
25	//	                      nine digits is accepted only when every digit past
26	//	                      the ninth is zero, never truncated or rounded)
27	//	version       string   version (required, non-empty, valid Unicode text)
28	//	height        integer  block height (required, >= 0)
29	//	missed        integer  cumulative missed duties (required, >= 0)
30	type Heartbeat struct {
31		NodeID      string    `json:"node"`
32		Seq         int64     `json:"seq"`
33		CollectedAt time.Time `json:"collected_at"`
34		Version     string    `json:"version"`
35		Height      int64     `json:"height"`
36		Missed      int64     `json:"missed"`
37	}
38	
39	// heartbeatFields enumerates every field that must be explicitly provided.
40	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
41	
42	// fieldIssue classifies the way a field value violates a rule. Together with
43	// the field name and the offending numeric value it identifies the rule that
44	// failed, without carrying any wording. Each trust boundary renders the
45	// failure in its own message style and locates it in its own context, but the
46	// rules themselves — which values are legal — live in the check* functions
47	// below exactly once.
48	type fieldIssue int
49	
50	const (
51		issueEmpty            fieldIssue = iota // a required string is ""
52		issueInvalidUnicode                     // node id or version is not lossless text
53		issueNotPositive                        // integer must be > 0
54		issueNegative                           // integer must be >= 0
55		issueMissingInstant                     // collected_at is the zero instant
56		issueYearOutOfRange                     // collected_at year cannot be written by the saved format
57		issueOffsetOutOfRange                   // collected_at timezone offset is not a whole minute within ±23:59
58	)
59	
60	// fieldValueError names the field whose value rule was violated.
61	type fieldValueError struct {
62		field string
63		issue fieldIssue
64		value int64
65	}
66	
67	// checkNodeIDValue holds the single node-id value rule: non-empty, valid
68	// Unicode text. The raw-JSON boundary additionally checks the un-decoded
69	// token (see validateRawText); for a value already decoded from such a
70	// token the Unicode branch can never fire, but both submit entries and the
71	// stored-data read enforce the same rule through this one function.
72	func checkNodeIDValue(node string) *fieldValueError {
73		if node == "" {
74			return &fieldValueError{field: "node", issue: issueEmpty}
75		}
76		if !utf8.ValidString(node) {
77			return &fieldValueError{field: "node", issue: issueInvalidUnicode}
78		}
79		return nil
80	}
81	
82	// checkVersionValue holds the single version value rule: non-empty, valid
83	// Unicode text. The version is opaque text — Chinese, emoji and a literal "�"
84	// the user typed are all legal, and no format (digits and dots) is imposed —
85	// but it must be losslessly representable: a platform that silently rewrites
86	// invalid bytes to U+FFFD would merge distinct versions into one and make the
87	// version-skew judgement compare text the node never reported. The raw-JSON
88	// boundary additionally checks the un-decoded token (see validateRawText);
89	// for a value already decoded from such a token the Unicode branch can never
90	// fire, but both submit entries and the stored-data read enforce the same
91	// rule through this one function.
92	func checkVersionValue(version string) *fieldValueError {
93		if version == "" {
94			return &fieldValueError{field: "version", issue: issueEmpty}
95		}
96		if !utf8.ValidString(version) {
97			return &fieldValueError{field: "version", issue: issueInvalidUnicode}
98		}
99		return nil
100	}
101	
102	// checkPositiveInt holds the single positive-integer rule (seq).
103	func checkPositiveInt(field string, value int64) *fieldValueError {
104		if value <= 0 {
105			return &fieldValueError{field: field, issue: issueNotPositive, value: value}
106		}
107		return nil
108	}
109	
110	// checkNonNegativeInt holds the single non-negative-integer rule (height,
111	// missed). An explicit zero is genuine telemetry and passes.
112	func checkNonNegativeInt(field string, value int64) *fieldValueError {
113		if value < 0 {
114			return &fieldValueError{field: field, issue: issueNegative, value: value}
115		}
116		return nil
117	}
118	
119	// checkCollectedAtValue holds the context-free collected_at rules shared by
120	// every boundary:
121	//
122	//   - the instant must actually be present (not the zero time);
123	//   - its year must be 0000..9999, the four-digit range the saved RFC3339
124	//     form can write — a year outside it cannot be persisted at all;
125	//   - its UTC offset must be a whole number of minutes no larger than
126	//     ±23:59, the offsets the saved form can write exactly. A ±24:00 offset
127	//     is outside the 00..23 hour bound, and a sub-minute offset (e.g.
128	//     +08:00:30) would silently land on disk as a different instant.
129	//
130	// Checking the decoded instant covers a Heartbeat built directly in Go;
131	// values decoded from JSON text additionally pass validateCollectedAtText,
132	// because time.Parse folds an out-of-range textual offset (+00:60 -> +01:00)
133	// before an instant ever exists to inspect.
134	func checkCollectedAtValue(collected time.Time) *fieldValueError {
135		if collected.IsZero() {
136			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
137		}
138		if year := collected.Year(); year < minSavedYear || year > maxSavedYear {
139			return &fieldValueError{field: "collected_at", issue: issueYearOutOfRange, value: int64(year)}
140		}
141		if _, offset := collected.Zone(); !isWritableOffset(offset) {
142			return &fieldValueError{field: "collected_at", issue: issueOffsetOutOfRange, value: int64(offset)}
143		}
144		return nil
145	}
146	
147	// Year bounds of the four-digit RFC3339 year the saved format writes.
148	const (
149		minSavedYear = 0
150		maxSavedYear = 9999
151	)
152	
153	// maxWritableOffsetSeconds is 23:59, the largest magnitude UTC offset whose
154	// hour and minute fields both fit the RFC3339 numeric offset (hour 00..23,
155	// minute 00..59). 24:00 is out of range, not an alias for the next day.
156	const maxWritableOffsetSeconds = 23*3600 + 59*60
157	
158	// isWritableOffset reports whether a UTC offset in seconds can be written by
159	// the on-disk RFC3339 form without losing or folding anything: it must be a
160	// whole number of minutes (a sub-minute offset has no representation), and
161	// its magnitude must be no greater than ±23:59.
162	func isWritableOffset(offsetSeconds int) bool {
163		if offsetSeconds%60 != 0 {
164			return false
165		}
166		if offsetSeconds < 0 {
167			offsetSeconds = -offsetSeconds
168		}
169		return offsetSeconds <= maxWritableOffsetSeconds
170	}
171	
172	// formatOffsetSeconds renders a UTC offset in seconds the way it was
173	// declared: ±HH:MM for a whole-minute offset, ±HH:MM:SS when a sub-minute
174	// part is present, so an error can show the exact offset that could not be
175	// saved (e.g. +08:00:45 or -24:00).
176	func formatOffsetSeconds(seconds int) string {
177		sign := "+"
178		if seconds < 0 {
179			sign = "-"
180			seconds = -seconds
181		}
182		hour := seconds / 3600
183		minute := (seconds % 3600) / 60
184		if rem := seconds % 60; rem != 0 {
185			return fmt.Sprintf("%s%02d:%02d:%02d", sign, hour, minute, rem)
186		}
187		return fmt.Sprintf("%s%02d:%02d", sign, hour, minute)
188	}
189	
190	// validateCollectedAtText guards the one gap in time.Parse(RFC3339) that the
191	// instant-level check cannot see: the standard library folds an out-of-range
192	// numeric timezone offset instead of rejecting it — "+00:60" parses as
193	// +01:00 and "+23:60" as +24:00 — and it accepts "+24:00"/"-24:00" even
194	// though the RFC3339 write layout cannot express them. The string has
195	// already passed time.Parse, so its shape is RFC3339 with a "Z" suffix or a
196	// six-character ±HH:MM suffix; here the offset's own hour and minute fields
197	// are required to be 00..23 and 00..59 with no carry-over between them.
198	func validateCollectedAtText(s string) error {
199		// "Z" is the only sign-less offset form; it denotes the zero offset.
200		if strings.HasSuffix(s, "Z") {
201			return nil
202		}
203		if len(s) < 6 {
204			return fmt.Errorf("timezone offset must be Z or ±HH:MM in %q", s)
205		}
206		off := s[len(s)-6:]
207		if (off[0] != '+' && off[0] != '-') || off[3] != ':' {
208			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
209		}
210		hour, ok1 := twoDecimalDigits(off[1:3])
211		minute, ok2 := twoDecimalDigits(off[4:6])
212		if !ok1 || !ok2 {
213			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
214		}
215		if hour > 23 {
216			return fmt.Errorf("timezone offset %s has hour %02d, must be 00-23", off, hour)
217		}
218		if minute > 59 {
219			return fmt.Errorf("timezone offset %s has minute %02d, must be 00-59 (out-of-range minutes are not folded into the hour)", off, minute)
220		}
221		return nil
222	}
223	
224	// twoDecimalDigits parses exactly two ASCII decimal digits.
225	func twoDecimalDigits(s string) (int, bool) {
226		if len(s) != 2 || s[0] < '0' || s[0] > '9' || s[1] < '0' || s[1] > '9' {
227			return 0, false
228		}
229		return int(s[0]-'0')*10 + int(s[1]-'0'), true
230	}
231	
232	// validateCollectedAtFraction guards the second gap in time.Parse(RFC3339)
233	// that the instant-level check cannot see: the standard library silently
234	// truncates a fractional second beyond nine digits — with either of the
235	// decimal separators it accepts, "." and "," — so ".1234567891" and
236	// ".1234567892", and likewise ",1234567891" and ",1234567892", both decode
237	// to the same nanosecond instant even though the node reported two different
238	// moments. Heartbeat collection times must be preserved exactly, so such
239	// input is refused under the same rule no matter which separator was written,
240	// never truncated or rounded. A fraction of at most nine digits always parses
241	// exactly, and a longer fraction is accepted only when every digit past the
242	// ninth is zero — the text then denotes the same instant as its nine-digit
243	// prefix (".1234567890" and ",123456789000" are both ".123456789"). The
244	// string has already passed time.Parse, so the "." or "," found here can only
245	// introduce the fractional second and what follows it up to the zone suffix
246	// is all digits.
247	func validateCollectedAtFraction(s string) error {
248		sep := strings.IndexAny(s, ".,")
249		if sep < 0 {
250			return nil
251		}
252		end := sep + 1
253		for end < len(s) && s[end] >= '0' && s[end] <= '9' {
254			end++
255		}
256		frac := s[sep:end] // separator plus digits, quoted verbatim in errors
257		digits := frac[1:]
258		if len(digits) <= 9 {
259			return nil
260		}
261		for i := 9; i < len(digits); i++ {
262			if digits[i] != '0' {
263				return fmt.Errorf("fractional second %s cannot be represented exactly at nanosecond precision: digit %d is not zero, and digits past the ninth must all be zero (the instant is never truncated or rounded)", frac, i+1)
264			}
265		}
266		return nil
267	}
268	
269	// ParseHealthQueryTime parses an explicitly given health-query instant (the
270	// CLI's --at) under exactly the text rules a collected_at timestamp is held
271	// to, because the query instant is compared against saved collection times
272	// and must be the precise moment the user wrote: RFC3339 with an explicit
273	// timezone; a numeric offset whose hour is 00-23 and minute 00-59 with no
274	// carry-over (±24:00 and a folded offset such as +00:60 are refused, while
275	// "Z", "-00:00" and ±23:59 stay legal); and a fractional second — written
276	// with "." or "," — that is exact at nanosecond precision (more than nine
277	// digits only when every digit past the ninth is zero, never truncated or
278	// rounded). time.Parse alone folds out-of-range offsets and truncates long
279	// fractions, which would let a moment the user never wrote judge a node
280	// online or offline, so both text-level guards run after it.
281	func ParseHealthQueryTime(s string) (time.Time, error) {
282		t, err := time.Parse(time.RFC3339, s)
283		if err != nil {
284			return time.Time{}, fmt.Errorf("must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
285		}
286		if err := validateCollectedAtText(s); err != nil {
287			return time.Time{}, err
288		}
289		if err := validateCollectedAtFraction(s); err != nil {
290			return time.Time{}, err
291		}
292		return t, nil
293	}
294	
295	// checkHeartbeatValues runs every context-free field-value rule in the single
296	// rejection order shared by the direct-submit and stored-data boundaries:
297	// node, seq, version, height, missed, then collected_at. It deliberately does
298	// NOT compare against a receive time: reading saved history has no receive
299	// time, and that submit-only rule lives in checkCollectedAtTiming.
300	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
301		if e := checkNodeIDValue(h.NodeID); e != nil {
302			return e
303		}
304		if e := checkPositiveInt("seq", h.Seq); e != nil {
305			return e
306		}
307		if e := checkVersionValue(h.Version); e != nil {
308			return e
309		}
310		if e := checkNonNegativeInt("height", h.Height); e != nil {
311			return e
312		}
313		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
314			return e
315		}
316		return checkCollectedAtValue(h.CollectedAt)
317	}
318	
319	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
320	// submission only: a collection time later than the receive time is refused;
321	// the same instant expressed in another timezone is equal and allowed. The
322	// stored-data read path never calls this, so reading history introduces no
323	// current time and no extra time limit.
324	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
325		if collected.After(receiveTime) {
326			return fmt.Errorf("collected_at %s is later than receive time %s",
327				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
328		}
329		return nil
330	}
331	
332	// directError renders a field rule failure in ValidateHeartbeat's wording,
333	// used when a caller submits an already constructed Heartbeat.
334	func (e *fieldValueError) directError() error {
335		switch {
336		case e.field == "node" && e.issue == issueEmpty:
337			return fmt.Errorf("node id is empty")
338		case e.field == "node" && e.issue == issueInvalidUnicode:
339			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
340		case e.field == "seq":
341			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
342		case e.field == "version" && e.issue == issueInvalidUnicode:
343			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
344		case e.field == "version":
345			return fmt.Errorf("version is empty")
346		case e.field == "height":
347			return fmt.Errorf("height must be >= 0, got %d", e.value)
348		case e.field == "missed":
349			return fmt.Errorf("missed must be >= 0, got %d", e.value)
350		case e.field == "collected_at":
351			switch e.issue {
352			case issueMissingInstant:
353				return fmt.Errorf("collected_at is missing or invalid")
354			case issueYearOutOfRange:
355				return fmt.Errorf("collected_at year %d cannot be saved: year must be 0000-9999", e.value)
356			case issueOffsetOutOfRange:
357				return fmt.Errorf("collected_at timezone offset %s cannot be saved exactly: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
358			}
359			return fmt.Errorf("collected_at is missing or invalid")
360		default:
361			return fmt.Errorf("field %q has an invalid value", e.field)
362		}
363	}
364	
365	// decodeError renders a field rule failure in the wording used while decoding
366	// a strict JSON object (submit input and stored records alike).
367	func (e *fieldValueError) decodeError() error {
368		switch {
369		case e.field == "node" && e.issue == issueInvalidUnicode:
370			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
371		case e.field == "node":
372			return fmt.Errorf("node must not be empty")
373		case e.field == "seq":
374			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
375		case e.field == "version" && e.issue == issueInvalidUnicode:
376			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
377		case e.field == "version":
378			return fmt.Errorf("version must not be empty")
379		case e.field == "height":
380			return fmt.Errorf("height must be >= 0, got %d", e.value)
381		case e.field == "missed":
382			return fmt.Errorf("missed must be >= 0, got %d", e.value)
383		case e.field == "collected_at":
384			switch e.issue {
385			case issueMissingInstant:
386				return fmt.Errorf("collected_at is missing or invalid")
387			case issueYearOutOfRange:
388				return fmt.Errorf("collected_at year %d is out of range: year must be 0000-9999", e.value)
389			case issueOffsetOutOfRange:
390				return fmt.Errorf("collected_at timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
391			}
392			return fmt.Errorf("collected_at is missing or invalid")
393		default:
394			return fmt.Errorf("invalid value for field %q", e.field)
395		}
396	}
397	
398	// storedError renders a field rule failure for a record read from a saved
399	// file, prefixing the 1-based record position as stored-data errors do.
400	func (e *fieldValueError) storedError(position int) error {
401		switch {
402		case (e.field == "node" || e.field == "version") && e.issue == issueInvalidUnicode:
403			return fmt.Errorf("record %d: field %q is not valid Unicode text", position, e.field)
404		case e.field == "node" || e.field == "version":
405			return fmt.Errorf("record %d: field %q must not be empty", position, e.field)
406		case e.field == "seq":
407			return fmt.Errorf("record %d: field %q must be a positive integer, got %d", position, e.field, e.value)
408		case e.field == "height" || e.field == "missed":
409			return fmt.Errorf("record %d: field %q must be >= 0, got %d", position, e.field, e.value)
410		case e.field == "collected_at":
411			switch e.issue {
412			case issueYearOutOfRange:
413				return fmt.Errorf("record %d: field %q year %d is out of range: year must be 0000-9999", position, e.field, e.value)
414			case issueOffsetOutOfRange:
415				return fmt.Errorf("record %d: field %q timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", position, e.field, formatOffsetSeconds(int(e.value)))
416			}
417			return fmt.Errorf("record %d: field %q is missing or invalid", position, e.field)
418		default:
419			return fmt.Errorf("record %d: field %q has an invalid value", position, e.field)
420		}
421	}
422	
423	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
424	// the moment the platform received the batch; a collection time later than
425	// receive time is rejected. The field-value rules are shared with JSON
426	// parsing and the stored-file read path via checkHeartbeatValues; only the
427	// receive-time comparison is submit-specific.
428	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
429		if e := checkHeartbeatValues(h); e != nil {
430			return e.directError()
431		}
432		return checkCollectedAtTiming(h.CollectedAt, receiveTime)
433	}
434	
435	// Equal reports whether two records are the same telemetry. Collection times
436	// are compared as instants, so the same moment expressed in different
437	// timezones compares equal.
438	func (h Heartbeat) Equal(o Heartbeat) bool {
439		return h.NodeID == o.NodeID &&
440			h.Seq == o.Seq &&
441			h.Version == o.Version &&
442			h.Height == o.Height &&
443			h.Missed == o.Missed &&
444			h.CollectedAt.Equal(o.CollectedAt)
445	}
446	
447	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
448	// be explicitly provided; missing or unknown fields are rejected with a
449	// specific reason.
450	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
451		var raw []json.RawMessage
452		if err := json.Unmarshal(data, &raw); err != nil {
453			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
454		}
455		if len(raw) == 0 {
456			return nil, fmt.Errorf("no heartbeat records provided")
457		}
458		records := make([]Heartbeat, 0, len(raw))
459		for i, r := range raw {
460			h, err := parseOneHeartbeat(r, receiveTime)
461			if err != nil {
462				return nil, fmt.Errorf("record %d: %w", i+1, err)
463			}
464			records = append(records, h)
465		}
466		return records, nil
467	}
468	
469	// rejectNull reports an error when a required field's JSON value is null.
470	// A null value means the node did not report the field, which must not be
471	// silently saved as the zero value.
472	func rejectNull(raw json.RawMessage, field string) error {
473		if bytes.Equal(raw, []byte("null")) {
474			return fmt.Errorf("%s must not be null", field)
475		}
476		return nil
477	}
478	
479	// objectFields collects the fields of one JSON object while enforcing the
480	// single field-uniqueness rule shared by every strict decoder in this
481	// package: within one object, a field name may appear only once. Names are
482	// compared as the JSON strings they decode to, so a plain spelling and a
483	// Unicode-escaped spelling of the same name collide, whether the repeated
484	// value is identical or different. The rule is scoped to the current object:
485	// the same field name appearing in another heartbeat object is unrelated.
486	// Both the submit-input decoder (decodeStrictHeartbeatObject) and the
487	// stored-file envelope decoder (decodeStrictNodeFile) apply the rule through
488	// this type; each boundary keeps its own error wording and its own check
489	// ordering for the rejection.
490	//
491	// A nil map value means the name has been seen but its value not decoded
492	// yet; once decoded, the value is stored under the name.
493	type objectFields map[string]json.RawMessage
494	
495	// check records one occurrence of a field name and reports whether the name
496	// already appeared in this object (duplicate == true).
497	func (o objectFields) check(name string) (duplicate bool) {
498		if _, exists := o[name]; exists {
499			return true
500		}
501		o[name] = nil
502		return false
503	}
504	
505	// has reports whether the field name appeared in this object.
506	func (o objectFields) has(name string) bool {
507		_, exists := o[name]
508		return exists
509	}
510	
511	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
512	// Heartbeat while enforcing the field rules at every trust boundary: all
513	// fields must be present and non-null, unknown fields are rejected, and a
514	// field may never appear twice in the same object — even with the same
515	// value, and even when one spelling uses a JSON Unicode escape denoting the
516	// same key (the shared objectFields rule). A plain struct/map unmarshal
517	// would instead keep the last
518	// occurrence and let an absent field masquerade as the zero value. Both the
519	// submit input path and the stored-file read path must use it.
520	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
521		// Walk the object with a streaming decoder so duplicate field names are
522		// detected. Field names are compared as the JSON string they represent:
523		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
524		// would silently keep only the last occurrence.
525		dec := json.NewDecoder(bytes.NewReader(raw))
526		tok, err := dec.Token()
527		if err != nil {
528			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
529		}
530		if d, ok := tok.(json.Delim); !ok || d != '{' {
531			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
532		}
533	
534		fields := objectFields{}
535		for dec.More() {
536			keyTok, err := dec.Token()
537			if err != nil {
538				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
539			}
540			key, ok := keyTok.(string)
541			if !ok {
542				return Heartbeat{}, fmt.Errorf("field name must be a string")
543			}
544			if fields.check(key) {
545				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
546			}
547			var val json.RawMessage
548			if err := dec.Decode(&val); err != nil {
549				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
550			}
551			fields[key] = val
552		}
553		// Consume the closing brace.
554		if _, err := dec.Token(); err != nil {
555			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
556		}
557	
558		for _, f := range heartbeatFields {
559			if !fields.has(f) {
560				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
561			}
562		}
563		for k := range fields {
564			if !containsString(heartbeatFields, k) {
565				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
566			}
567		}
568	
569		var h Heartbeat
570	
571		if err := rejectNull(fields["node"], "node"); err != nil {
572			return Heartbeat{}, err
573		}
574		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
575			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
576		}
577		if err := validateRawText(fields["node"], "node"); err != nil {
578			return Heartbeat{}, err
579		}
580		if e := checkNodeIDValue(h.NodeID); e != nil {
581			return Heartbeat{}, e.decodeError()
582		}
583	
584		if err := rejectNull(fields["seq"], "seq"); err != nil {
585			return Heartbeat{}, err
586		}
587		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
588			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
589		}
590		if e := checkPositiveInt("seq", h.Seq); e != nil {
591			return Heartbeat{}, e.decodeError()
592		}
593	
594		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
595			return Heartbeat{}, err
596		}
597		var collectedStr string
598		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
599			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
600		}
601		t, err := time.Parse(time.RFC3339, collectedStr)
602		if err != nil {
603			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
604		}
605		// time.Parse folds out-of-range numeric offsets (+00:60 -> +01:00) and
606		// accepts +24:00; verify the written offset before trusting the fold.
607		if err := validateCollectedAtText(collectedStr); err != nil {
608			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
609		}
610		// time.Parse also silently truncates a fractional second beyond nine
611		// digits for both accepted separators ("." and ","); the collection
612		// moment must be exactly representable.
613		if err := validateCollectedAtFraction(collectedStr); err != nil {
614			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
615		}
616		h.CollectedAt = t
617	
618		if err := rejectNull(fields["version"], "version"); err != nil {
619			return Heartbeat{}, err
620		}
621		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
622			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
623		}
624		if err := validateRawText(fields["version"], "version"); err != nil {
625			return Heartbeat{}, err
626		}
627		if e := checkVersionValue(h.Version); e != nil {
628			return Heartbeat{}, e.decodeError()
629		}
630	
631		if err := rejectNull(fields["height"], "height"); err != nil {
632			return Heartbeat{}, err
633		}
634		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
635			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
636		}
637		if e := checkNonNegativeInt("height", h.Height); e != nil {
638			return Heartbeat{}, e.decodeError()
639		}
640	
641		if err := rejectNull(fields["missed"], "missed"); err != nil {
642			return Heartbeat{}, err
643		}
644		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
645			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
646		}
647		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
648			return Heartbeat{}, e.decodeError()
649		}
650	
651		return h, nil
652	}
653	
654	// validateRawText checks the raw JSON string token of a text field (node or
655	// version) before its decoded value is trusted. encoding/json silently rewrites
656	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
657	// would merge distinct texts into one replacement-char value: distinct node
658	// ids would collapse and break the ownership check against stored files, and
659	// distinct versions would collapse into text the node never reported,
660	// corrupting dedup and the version-skew judgement. The raw token must decode
661	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
662	// escape must be a valid scalar value or a properly paired high/low
663	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
664	// user typed and is accepted; only undecodable input is rejected. A \\
665	// escape is consumed as a unit, so text that genuinely contains a backslash
666	// followed by "u" and hex digits is never re-interpreted as an escape.
667	func validateRawText(raw json.RawMessage, field string) error {
668		raw = bytes.TrimSpace(raw)
669		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
670			return fmt.Errorf("%s must be a string", field)
671		}
672		s := raw[1 : len(raw)-1]
673		for i := 0; i < len(s); {
674			c := s[i]
675			if c == '\\' {
676				if i+1 >= len(s) {
677					return fmt.Errorf("%s contains a truncated escape", field)
678				}
679				if s[i+1] != 'u' {
680					i += 2
681					continue
682				}
683				if i+6 > len(s) {
684					return fmt.Errorf("%s contains a truncated \\u escape", field)
685				}
686				r, err := parseHex4(s[i+2 : i+6])
687				if err != nil {
688					return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
689				}
690				switch {
691				case r >= 0xD800 && r <= 0xDBFF:
692					// A high surrogate is only valid when immediately followed
693					// by a low-surrogate \u escape.
694					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
695						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
696					}
697					lo, err := parseHex4(s[i+8 : i+12])
698					if err != nil {
699						return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
700					}
701					if lo < 0xDC00 || lo > 0xDFFF {
702						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
703					}
704					i += 12
705				case r >= 0xDC00 && r <= 0xDFFF:
706					return fmt.Errorf("%s contains an unpaired low surrogate \\u%04X", field, r)
707				default:
708					i += 6
709				}
710				continue
711			}
712			if c < utf8.RuneSelf {
713				i++
714				continue
715			}
716			// A valid multi-byte rune decodes with size >= 2; size 1 means the
717			// bytes are not valid UTF-8 (including surrogate encodings).
718			_, size := utf8.DecodeRune(s[i:])
719			if size == 1 {
720				return fmt.Errorf("%s contains invalid UTF-8 at byte offset %d", field, i)
721			}
722			i += size
723		}
724		return nil
725	}
726	
727	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
728	func parseHex4(b []byte) (rune, error) {
729		v := 0
730		for _, c := range b {
731			var d int
732			switch {
733			case '0' <= c && c <= '9':
734				d = int(c - '0')
735			case 'a' <= c && c <= 'f':
736				d = int(c-'a') + 10
737			case 'A' <= c && c <= 'F':
738				d = int(c-'A') + 10
739			default:
740				return 0, fmt.Errorf("invalid hex digit %q", c)
741			}
742			v = v*16 + d
743		}
744		return rune(v), nil
745	}
746	
747	// parseOneHeartbeat decodes one submit-input record and applies the
748	// submit-only rule that collection time cannot be later than receive time.
749	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
750		h, err := decodeStrictHeartbeatObject(raw)
751		if err != nil {
752			return Heartbeat{}, err
753		}
754		if err := checkCollectedAtTiming(h.CollectedAt, receiveTime); err != nil {
755			return Heartbeat{}, err
756		}
757		return h, nil
758	}
759	
760	func containsString(list []string, s string) bool {
761		for _, v := range list {
762			if v == s {
763				return true
764			}
765		}
766		return false
767	}
