// last occurrence and let an absent field masquerade as the zero value. Both
// the submit input path and the stored-file read path must use it.
func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
	// The shared walker streams the object and reports shape failures as a
	// structured strictObjectError; this callback adds the one submit-side
	// rule that must fire before a value is decoded: a repeated field name is
	// a duplicate, names compared as the JSON string they represent (so
	// "missed" and "missed" collide). A map-based unmarshal would
	// silently keep only the last occurrence.
	fields, err := walkStrictObject(raw, false, func(fields objectFields, key string, _ func() (json.RawMessage, error)) error {
		if fields.check(key) {
			return &strictObjectError{issue: issueDuplicateField, field: key}
		}
		return nil
	})
	if err != nil {
		return Heartbeat{}, asStrictObjectError(err, (*strictObjectError).plainError)
	}

	if f, ok := missingField(fields, heartbeatFields); ok {
		return Heartbeat{}, fmt.Errorf("missing required field %q", f)
	}
	if k, ok := unknownField(fields, heartbeatFields); ok {
		return Heartbeat{}, fmt.Errorf("unknown field %q", k)
	}

