		return nil, asStrictObjectError(err, (*strictObjectError).envelopeError)
	}

	for _, required := range []string{"format", "checksum", "records"} {
		if !fields.has(required) {
			return nil, fmt.Errorf("missing required envelope field %q", required)
		}
	}

	nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
	for i, raw := range records {
		h, err := decodeStrictHeartbeatObject(raw)
		if err != nil {
			return nil, fmt.Errorf("record %d: %w", i+1, err)
		}
		nf.Records = append(nf.Records, h)
	}
