19	//   - the caller decides which fields are required or known, in its own order
20	//     and with its own wording.
21	//
22	// What the two boundaries do NOT share is the meaning and ordering of a
23	// rejection: submitted input is illegal user content ("record N: ...", a
24	// non-zero command exit, no success count), while a node file that fails the
25	// same rules is saved-data corruption. The rules therefore live here once;
26	// walkStrictObject reports them as a structured strictObjectError, and each
27	// boundary renders that failure in its own message style (plainError for
28	// submitted records, envelopeError for the stored file).
29	
30	// objectFields collects the fields of one JSON object while enforcing the
31	// single field-uniqueness rule shared by every strict decoder in this
32	// package. Names are compared as the JSON strings they decode to, so a plain
33	// spelling and a Unicode-escaped spelling of the same name collide, whether
34	// the repeated value is identical or different. The rule is scoped to the
35	// current object: the same field name appearing in another heartbeat object
36	// is unrelated. Both the submit-input decoder and the stored-file envelope
37	// decoder apply the rule through this type; each boundary keeps its own error
38	// wording and its own check ordering for the rejection.
39	//
40	// A nil map value means the name has been seen but its value not captured
41	// yet; walkStrictObject stores the raw value there once the member has been
42	// fully read.
43	type objectFields map[string]json.RawMessage
44	
45	// check records one occurrence of a field name and reports whether the name
46	// already appeared in this object (duplicate == true).
47	func (o objectFields) check(name string) (duplicate bool) {
48		if _, exists := o[name]; exists {
49			return true
50		}
51		o[name] = nil
52		return false
53	}
54	
55	// has reports whether the field name appeared in this object.
56	func (o objectFields) has(name string) bool {
57		_, exists := o[name]
58		return exists
59	}
60	
61	// missingField returns the first name in required (in the given order) that
62	// did not appear in the object. Both boundaries list required fields in a
63	// fixed order so a multi-field omission names the same field every time.
64	func missingField(fields objectFields, required []string) (string, bool) {
65		for _, f := range required {
66			if !fields.has(f) {
67				return f, true
68			}
69		}
70		return "", false
71	}
72	
73	// unknownField returns one name that appeared in the object but is not in
74	// known. It preserves the submit decoder's post-decode unknown-field check;
75	// the envelope rejects an unknown field inline, in document order.
76	func unknownField(fields objectFields, known []string) (string, bool) {
77		for name := range fields {
78			if !containsString(known, name) {
79				return name, true
80			}
81		}
82		return "", false
83	}
84	
85	func containsString(list []string, s string) bool {
86		for _, v := range list {
87			if v == s {
88				return true
89			}
90		}
91		return false
92	}
93	
94	// strictObjectIssue classifies a structural violation found while walking one
95	// JSON object, carrying no wording of its own. Each trust boundary renders it
96	// itself (plainError versus envelopeError), the same split fieldValueError
97	// uses for field-value rules.
98	type strictObjectIssue int
99	
100	const (
101		issueOpenInvalid        strictObjectIssue = iota // cannot read the first token
102		issueNotObject                                   // the first token is not '{'
103		issueFieldNameInvalid                            // cannot read a member name token
104		issueFieldNameNotString                          // member name is not a JSON string
105		issueValueInvalid                                // member value cannot be read as raw JSON
106		issueDuplicateField                              // a decoded field name repeats in the object
107		issueCloseInvalid                                // cannot read the closing '}'
108		issueTrailingData                                // content follows the single object
109	)
110	
111	// strictObjectError is a structural rule failure from walkStrictObject. Field
112	// carries the offending member name for the per-field issues; err carries the
113	// underlying encoding/json error.
114	type strictObjectError struct {
115		issue strictObjectIssue
116		field string
117		err   error
118	}
119	
120	func (e *strictObjectError) Error() string { return e.plainError().Error() }
121	
122	// plainError renders the failure in the wording used while decoding a strict
123	// JSON object that is itself user input (a submitted heartbeat record).
124	func (e *strictObjectError) plainError() error {
125		switch e.issue {
126		case issueOpenInvalid:
127			return fmt.Errorf("record must be a JSON object: %w", e.err)
128		case issueNotObject:
129			return fmt.Errorf("record must be a JSON object")
130		case issueFieldNameInvalid:
131			return fmt.Errorf("invalid field: %w", e.err)
132		case issueFieldNameNotString:
133			return fmt.Errorf("field name must be a string")
134		case issueValueInvalid:
135			return fmt.Errorf("invalid value for field %q: %w", e.field, e.err)
136		case issueDuplicateField:
137			return fmt.Errorf("duplicate field %q", e.field)
138		case issueCloseInvalid:
139			return fmt.Errorf("invalid record: %w", e.err)
140		case issueTrailingData:
141			if e.err != nil {
142				return fmt.Errorf("invalid record: %w", e.err)
143			}
144			return fmt.Errorf("invalid record: unexpected data after the object")
145		default:
146			return fmt.Errorf("invalid record")
147		}
148	}
149	
150	// envelopeError renders the failure as saved-data corruption wording, where
151	// the object is the node-file envelope rather than a submitted record.
152	func (e *strictObjectError) envelopeError() error {
153		switch e.issue {
154		case issueOpenInvalid:
155			return fmt.Errorf("invalid JSON: %w", e.err)
156		case issueNotObject:
157			return fmt.Errorf("invalid JSON: file must be a JSON object")
158		case issueFieldNameInvalid:
159			return fmt.Errorf("invalid JSON: %w", e.err)
160		case issueFieldNameNotString:
161			return fmt.Errorf("invalid JSON: envelope field name must be a string")
162		case issueValueInvalid:
163			return fmt.Errorf("invalid value for envelope field %q: %w", e.field, e.err)
164		case issueDuplicateField:
165			return fmt.Errorf("duplicate envelope field %q", e.field)
166		case issueCloseInvalid:
167			return fmt.Errorf("invalid JSON: %w", e.err)
168		case issueTrailingData:
169			if e.err != nil {
170				return fmt.Errorf("invalid JSON: %w", e.err)
171			}
172			return fmt.Errorf("invalid JSON: unexpected data after the envelope object")
173		default:
174			return fmt.Errorf("invalid JSON")
175		}
176	}
177	
178	// asStrictObjectError renders a walker failure with the boundary's renderer,
179	// leaving any other error (a boundary-specific wording produced inside the
180	// field callback) untouched.
181	func asStrictObjectError(err error, render func(*strictObjectError) error) error {
182		var se *strictObjectError
183		if errors.As(err, &se) {
184			return render(se)
185		}
186		return err
187	}
188	
189	// objectFieldFunc inspects one object member in document order. name is the
190	// JSON-decoded member name. decodeValue reads the member's raw JSON value and
191	// advances the stream; it is idempotent and walkStrictObject calls it once
192	// more after the callback returns, so a callback may choose WHEN to read the
193	// value relative to its own checks — the submit decoder rejects a duplicate
194	// name before decoding its value, while the envelope decoder reads the value
195	// first — but the value is always consumed exactly once and semantic decoding
196	// stays entirely the callback's job. A callback's own non-structural error
197	// (distinct wording such as a null/type rejection) is passed through
198	// unchanged.
199	type objectFieldFunc func(fields objectFields, name string, decodeValue func() (json.RawMessage, error)) error
200	
201	// walkStrictObject streams exactly one JSON object from raw, invoking visit
202	// once per member in document order. It enforces the shared structural rules
203	// (object shape, field-name decoding, raw-value readability) and records each
204	// decoded name in the returned objectFields, where visit applies the shared
205	// uniqueness rule through fields.check. When rejectTrailing is true, nothing
206	// may follow the object's closing brace; submitted record elements never set
207	// it (each array element is already exactly one value), the on-disk envelope
208	// does. Structural failures come back as *strictObjectError, rendered by each
209	// boundary; errors produced by visit pass through verbatim.
210	func walkStrictObject(raw json.RawMessage, rejectTrailing bool, visit objectFieldFunc) (objectFields, error) {
211		dec := json.NewDecoder(bytes.NewReader(raw))
212		tok, err := dec.Token()
213		if err != nil {
214			return nil, &strictObjectError{issue: issueOpenInvalid, err: err}
215		}
216		if d, ok := tok.(json.Delim); !ok || d != '{' {
217			return nil, &strictObjectError{issue: issueNotObject}
218		}
219	
220		fields := objectFields{}
221		for dec.More() {
222			keyTok, err := dec.Token()
223			if err != nil {
224				return nil, &strictObjectError{issue: issueFieldNameInvalid, err: err}
225			}
226			key, ok := keyTok.(string)
227			if !ok {
228				return nil, &strictObjectError{issue: issueFieldNameNotString}
229			}
230	
231			var (
232				rawVal    json.RawMessage
233				valueRead bool
234				valueErr  *strictObjectError
235			)
236			decodeValue := func() (json.RawMessage, error) {
237				if !valueRead {
238					valueRead = true
239					if err := dec.Decode(&rawVal); err != nil {
240						valueErr = &strictObjectError{issue: issueValueInvalid, field: key, err: err}
241					}
242				}
243				if valueErr != nil {
244					return rawVal, valueErr
245				}
246				return rawVal, nil
247			}
248	
249			if err := visit(fields, key, decodeValue); err != nil {
250				return nil, err
251			}
252			// On success the callback may have declined to read the value (the
253			// submit duplicate check happens before reading); decodeValue is
254			// idempotent and fills rawVal, so this either fetches it now or
255			// reuses the cached one.
256			if _, err := decodeValue(); err != nil {
257				return nil, err
258			}
259			fields[key] = rawVal
260		}
261	
262		// Consume the closing brace.
263		if _, err := dec.Token(); err != nil {
264			return nil, &strictObjectError{issue: issueCloseInvalid, err: err}
265		}
266		if rejectTrailing {
267			// Nothing may follow the single object.
268			if _, err := dec.Token(); err != io.EOF {
269				if err == nil {
270					return nil, &strictObjectError{issue: issueTrailingData}
271				}
272				return nil, &strictObjectError{issue: issueTrailingData, err: err}
273			}
274		}
275		return fields, nil
276	}
